class LocalActionTests(unittest.TestCase):
    def setUp(self):self.o=owner_for();self.ctx=collect(capture(self.o),'سند نمونه');self.key='local:'+self.o.events[0]['id'];self.request=lambda *a,**kw:None
    def action(self,type,changes,target=None):return normalize_action(dict(type=type,changes=changes,**({'target':target} if target else {})),self.ctx)
    def test_backup_requires_explicit_request_and_rejects_model_path(self):
        ctx=collect(capture(self.o),'نسخه پشتیبان تهیه کن')
        self.assertEqual(normalize_action({'type':'backup_create'},ctx),{'type':'backup_create'})
        for action in ({'type':'backup_create','changes':{'path':'arbitrary'}},{'type':'backup_create','path':'arbitrary'}):
            with self.assertRaises(ValueError):normalize_action(action,ctx)
        with self.assertRaises(ValueError):normalize_action({'type':'backup_create'},self.ctx)
    def test_reminder_delete_is_explicit_and_moves_to_trash(self):
        ctx=collect(capture(self.o),'یادآور بررسی سند نمونه را حذف کن');action={'type':'reminder_delete','target':self.key}
        self.assertTrue(execute(self.o,[action],ctx,self.request)[0]['ok']);self.assertFalse(self.o.events);self.assertEqual(self.o.data['event_trash'][0]['event']['title'],'بررسی سند نمونه')
