        with self.assertRaises(ValueError):parse_answer(json.dumps(dict(reply='انجام',actions=[raw]),ensure_ascii=False),ctx)
        raw['changes']['lead_days']=[3];reply,actions=parse_answer(json.dumps(dict(reply='انجام',actions=[raw]),ensure_ascii=False),ctx);self.assertEqual(actions[0]['changes']['lead_days'],[3])
        ctx=collect(capture(self.o),'برای بررسی سند نمونه ۳ روز، یک روز قبل و روز موعد یادآوری تنظیم کن');raw['changes']['lead_days']=[3,1,0];self.assertEqual(parse_answer(json.dumps(dict(reply='انجام',actions=[raw]),ensure_ascii=False),ctx)[1][0]['changes']['lead_days'],[3,1,0])
        ctx=collect(capture(self.o),'برای بررسی سند نمونه از پنج روز قبل هر روز و روز موعد یادآوری تنظیم کن');raw['changes']['lead_days']=[5,4,3,2,1,0];self.assertEqual(parse_answer(json.dumps(dict(reply='انجام',actions=[raw]),ensure_ascii=False),ctx)[1][0]['changes']['lead_days'],[5,4,3,2,1,0])
        raw['changes']['lead_days']=[5,3,2,1,0]
        with self.assertRaises(ValueError):parse_answer(json.dumps(dict(reply='انجام',actions=[raw]),ensure_ascii=False),ctx)
        ctx=collect(capture(self.o),'برای بررسی سند نمونه سی روز قبل یادآوری تنظیم کن');raw['changes']['lead_days']=[30];self.assertEqual(parse_answer(json.dumps(dict(reply='انجام',actions=[raw]),ensure_ascii=False),ctx)[1][0]['changes']['lead_days'],[30])
