    def test_reminder_date_must_be_grounded_in_user_or_explicit_reference(self):
        raw=dict(type='reminder_create',changes=dict(title='تماس با مشتری',date_jalali='1405/09/01'))
        missing=collect(capture(self.o),'برای تماس با مشتری یادآور بساز')
        with self.assertRaises(ValueError):normalize_action(raw,missing)
        from ai_chat_ui import clarification_request
        followup=clarification_request([dict(role='user',content='برای تماس با مشتری یادآور بساز'),dict(role='assistant',content='چه تاریخی یادآوری کنم؟')],'برای 1405/09/01 بذار')
        continued=collect(capture(self.o),followup);action=normalize_action(raw,continued);result=execute(self.o,[action],continued,self.request);self.assertTrue(result[0]['ok'],str(result));self.assertTrue(any(e['title']=='تماس با مشتری' for e in self.o.events))
        import jdatetime
        from datetime import timedelta
        from storage import today_j,jformat,normalize
        next_day=normalize(jformat(jdatetime.date.fromgregorian(date=today_j().togregorian()+timedelta(days=1))));followup=clarification_request([dict(role='user',content='برای تماس با مشتری یادآور بساز'),dict(role='assistant',content='چه تاریخی یادآوری کنم؟')],'برای فردا بذار');continued=collect(capture(self.o),followup);tomorrow=normalize_action(dict(type='reminder_create',changes=dict(title='تماس با مشتری',date_jalali=next_day)),continued);self.assertEqual(tomorrow['changes']['date_jalali'],next_day)
        second_day=normalize(jformat(jdatetime.date.fromgregorian(date=today_j().togregorian()+timedelta(days=2))));followup=clarification_request([dict(role='user',content='برای تماس با مشتری یادآور بساز'),dict(role='assistant',content='چه تاریخی یادآوری کنم؟')],'پسفردا ثبت کن');continued=collect(capture(self.o),followup);after=normalize_action(dict(type='reminder_create',changes=dict(title='تماس با مشتری',date_jalali=second_day)),continued);self.assertEqual(after['changes']['date_jalali'],second_day)
        with self.assertRaises(ValueError):normalize_action(dict(type='reminder_create',changes=dict(title='تماس با مشتری',date_jalali=next_day)),continued)
        today=normalize(jformat(today_j()));multi=collect(capture(self.o),'برای تماس با مشتری امروز و فردا یادآور بساز')
        for day in (today,next_day):self.assertEqual(normalize_action(dict(type='reminder_create',changes=dict(title='تماس با مشتری',date_jalali=day)),multi)['changes']['date_jalali'],day)
        with self.assertRaises(ValueError):normalize_action(dict(type='reminder_create',changes=dict(title='تماس با مشتری',date_jalali=second_day)),multi)
        invalid=collect(capture(self.o),'برای تماس با مشتری امروز در تاریخ 1405/13/40 یادآور بساز')
        with self.assertRaises(ValueError):normalize_action(dict(type='reminder_create',changes=dict(title='تماس با مشتری',date_jalali=today)),invalid)
        explicit=collect(capture(self.o),'برای تماس با مشتری در 1405/09/01 یادآور بساز')
        self.assertEqual(normalize_action(raw,explicit)['changes']['date_jalali'],'1405/09/01')
        wrong=dict(raw,changes=dict(raw['changes'],date_jalali='1405/09/02'))
        with self.assertRaises(ValueError):normalize_action(wrong,explicit)
        follow=collect(capture(self.o),'برای تماس با مشتری همون روز یادآور بساز',search_hint='قرار ملاقات در 1405/09/01')
        self.assertEqual(normalize_action(raw,follow)['changes']['date_jalali'],'1405/09/01')
        no_reference=collect(capture(self.o),'برای تماس با مشتری یادآور بساز',search_hint='قرار ملاقات در 1405/09/01')
        with self.assertRaises(ValueError):normalize_action(raw,no_reference)
        multiple=collect(capture(self.o),'برای تماس در 1405/09/01 و پیگیری در 1405/09/02 یادآور بساز')
        self.assertEqual(normalize_action(wrong,multiple)['changes']['date_jalali'],'1405/09/02')
        ambiguous=collect(capture(self.o),'برای تماس همان روز یادآور بساز',search_hint='یکی در 1405/09/01 و دیگری در 1405/09/02')
        with self.assertRaises(ValueError):normalize_action(raw,ambiguous)
        from ai_app_actions import ensure_requested_day
        interval=collect(capture(self.o),'از 1405/09/01 تا 1405/09/10 برای کارها برنامه بچین')
        ensure_requested_day('1405/09/05',interval,allow_range=True)
        with self.assertRaises(ValueError):ensure_requested_day('1405/09/11',interval,allow_range=True)
        with self.assertRaises(ValueError):ensure_requested_day('1405/09/05',interval)
