class SharedActionTests(unittest.TestCase):
    def setUp(self):
        self.tmp=tempfile.TemporaryDirectory();self.s=Store(Path(self.tmp.name)/'server');self.admin=self.s.bootstrap('admin','1','مدیر');self.staff_id=self.s.save_user(self.admin,dict(username='staff',password='1',fullname='همکار',memberships=[dict(company_id='mana',role='employee')]))['id'];self.other_id=self.s.save_user(self.admin,dict(username='other',password='1',fullname='دیگری',memberships=[dict(company_id='arka',role='employee')]))['id'];self.task=self.s.save_record(self.admin,'task',dict(title='کار همکار',due_date='1405/08/12',assignee_id=self.staff_id,status='draft',require_approval=True),'mana');self.foreign=self.s.save_record(self.admin,'task',dict(title='کار خصوصی دیگر',due_date='1405/08/12',assignee_id=self.other_id,status='draft'),'arka',private=True);self.server=RunningServer(Path(self.tmp.name)/'server','127.0.0.1',0);self.scope='__shared_chat__';self.room=self.s.workspace_group_create(self.admin,self.scope,'مشترک',[self.staff_id])['room'];self.client=Client('http://127.0.0.1:'+str(self.server.port));actor=self.client.login('staff','1');self.o=owner_for(actor,self.client);self.ctx=collect(capture(self.o),'کار همکار');self.key='work:'+self.task['id']
    def tearDown(self):self.client.session.close();self.server.close();self.tmp.cleanup()
    def run_actions(self,actions,ctx=None):return execute(self.o,actions,ctx or self.ctx,self.client.request)
    def test_chat_followup_supplies_missing_exact_message_without_sending_twice(self):
        from ai_chat_ui import clarification_request
        history=[dict(role='user',content='به گروه مشترک پیام بفرست'),dict(role='assistant',content='متن پیام چیست؟')]
        query=clarification_request(history,'جلسه فردا برگزار می‌شود');ctx=collect(capture(self.o),query);room=next(k for k,v in ctx['rooms'].items() if v['room']==self.room)
        action=normalize_action(dict(type='message_send',room_id=room,changes={'text':'جلسه فردا برگزار می‌شود'}),ctx)
        result=self.run_actions([action],ctx);self.assertTrue(result[0]['ok'],str(result));self.assertTrue(self.run_actions([action],ctx)[0]['ok']);messages=self.s.chat_list(self.client.user,self.scope,self.room)['items'];self.assertEqual(len(messages),1);self.assertEqual(messages[0]['text'],'جلسه فردا برگزار می‌شود')
        with self.assertRaises(ValueError):normalize_action(dict(type='message_send',room_id=room,changes={'text':'متن ساختگی'}),ctx)
