    def test_cash_amount_is_bound_to_currency_and_converts_tomans(self):
        from ai_app_actions import explicit_money_rials
        self.assertTrue(explicit_money_rials('۲ میلیون تومان',20000000));self.assertTrue(explicit_money_rials('۳ هزار ریال',3000));self.assertFalse(explicit_money_rials('۲ میلیون تومان و ۳ میلیون تومان',20000000));self.assertTrue(explicit_money_rials('۲.۵ میلیون تومان',25000000));self.assertFalse(explicit_money_rials('۲ میلیون تومان',2000000))
        self.assertFalse(explicit_money_rials('یک میلیون تومان و ۳ ریال',3));self.assertFalse(explicit_money_rials('۲.۵ میلیون تومان و ۳ ریال',3))
        self.assertTrue(explicit_money_rials('دو میلیون تومان',20000000));self.assertTrue(explicit_money_rials('بیست هزار ریال',20000));self.assertTrue(explicit_money_rials('بیست و دو میلیون تومان',220000000));self.assertFalse(explicit_money_rials('بیست و دو میلیون تومان',20000000));self.assertFalse(explicit_money_rials('منفی ۲ میلیون تومان',20000000));self.assertFalse(explicit_money_rials('- ۲ میلیون تومان',20000000))
        self.assertFalse(explicit_money_rials('بیست دو میلیون تومان',20000000))
        self.assertFalse(explicit_money_rials('صد و بیست و دو میلیون تومان',220000000));self.assertFalse(explicit_money_rials('بیست و سی میلیون تومان',300000000));self.assertTrue(explicit_money_rials('بیست و دو و نیم میلیون تومان',225000000))
        self.assertTrue(explicit_money_rials('دو و نیم میلیون تومان',25000000));self.assertTrue(explicit_money_rials('۲٫۵ میلیون تومان',25000000));self.assertFalse(explicit_money_rials('۰.۵ ریال',0));self.assertTrue(explicit_money_rials('۲ و نیم میلیون تومان',25000000));self.assertFalse(explicit_money_rials('منفی دو و نیم میلیون تومان',25000000))
        self.o.session_user=self.client.login('admin','1');raw={'type':'finance_cash','company_id':'mana','changes':{'direction':'expense','amount':'10000','date':'1405/08/02','reason':'اجاره'}}
