        arabic=collect(capture(self.o),'ثبت پرداخت نقد ۱۰۰۰۰ ريال اجاره شرکت مانا در تاریخ 1405/08/02');self.assertEqual(normalize_action(raw,arabic)['changes']['amount'],'10000')
        with self.assertRaises(ValueError):normalize_action(dict(raw,changes=dict(raw['changes'],amount='1000')),ctx)
